    FALSE: 3,

    /** A small integer {@link Value}. The next 4 bytes represent an integer. */
    SMALL_INT: 4,

    /** A small integer {@link Value}. The next 2 bytes represent an integer. */
    SMALL_INT_16: 5,

    /**
