const _bgra2rgbaInPlace = uint8a => {
    for (let i = 0; i < uint8a.length; i += 4) {
        const r = uint8a[i + 2];
        const b = uint8a[i + 0];
        uint8a[i + 2] = b;
        uint8a[i + 0] = r;
    }
    return uint8a;
};

/**
 * @augments FieldObject
 */
class ImageData extends FieldObject.define({
    /**
     * @memberof ImageData#
     * @type {Value}
     */
    WIDTH: 0,

    /**
     * @memberof ImageData#
     * @type {Value}
     */
    HEIGHT: 1,

    /**
     * @memberof ImageData#
     * @type {Value}
     */
    DEPTH: 2,

    /**
     * @memberof ImageData#
     * @type {Value}
     */
    BYTES: 4,

    /**
     * @memberof ImageData#
     * @type {Value}
     */
    COLORMAP: 5
}) {
    /**
     * @type {Uint8Array}
     */
    get decoded () {
        if (!this._decoded) {
            this._decoded = _bgra2rgbaInPlace(new Uint8Array(
                new SqueakImage().decode(
                    this.width.value,
                    this.height.value,
                    this.depth.value,
                    this.bytes.value,
                    this.colormap && this.colormap.map(color => color.valueOf())
                ).buffer
            ));
        }
        return this._decoded;
    }

    /**
     * @type {string}
     */
    get extension () {
        return 'uncompressed';
    }
}

